<script>document.querySelectorAll('.tab-btn').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));button.classList.add('active');document.getElementById('tab-'+button.dataset.tab).classList.add('active')})});document.querySelector('input[name="thumbnail"]')?.addEventListener('change',function(){const file=this.files[0];if(!file)return;document.getElementById('thumb-preview').innerHTML='<img src="'+URL.createObjectURL(file)+'" alt="Xem trước">';});</script>@endsection
